-- WARNING [EXP_CUSTOMER_ORDER_NUM]: comparison `customer_id = customer_id` compares a value with itself: always true unless NULL (check variable-port order in the source mapping)

with

srt_order_id as (
    -- SRT_ORDER_ID (Sorter on order_id asc, order_item_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        order_id as order_id,
        order_item_id as order_item_id,
        product_id as product_id,
        customer_id as customer_id,
        customer_name as customer_name,
        location_id as location_id,
        location_name as location_name,
        region as region,
        ordered_at_day as ordered_at_day,
        product_name as product_name,
        product_type as product_type,
        product_price as product_price,
        is_food_item as is_food_item,
        is_drink_item as is_drink_item,
        item_revenue as item_revenue,
        item_cogs as item_cogs,
        item_gross_profit as item_gross_profit,
        item_gross_margin_pct as item_gross_margin_pct,
        item_tax_estimate as item_tax_estimate,
        item_total_estimate as item_total_estimate,
        has_perishable_supply as has_perishable_supply
    from {{ ref('int_fl_js_marts_enriched__exp_item_calculations') }}
),

agg_items_by_order as (
    -- AGG_ITEMS_BY_ORDER (Aggregator) grouped by ORDER_ID
    select
        order_id as order_id,
        count(order_item_id) as item_lines,
        sum(item_revenue) as item_revenue,
        sum(item_cogs) as order_cogs,
        sum(item_gross_profit) as order_gross_profit,
        sum(is_food_item) as food_item_lines,
        sum(is_drink_item) as drink_item_lines
    from srt_order_id
    group by order_id
),

sq_stg_orders1 as (
    -- SQ_STG_ORDERS1 (Source Qualifier): reads STG_ORDERS
    select
        cast(order_id as varchar) as order_id,
        cast(customer_id as varchar) as customer_id,
        cast(location_id as varchar) as location_id,
        cast(ordered_at_day as timestamp) as ordered_at_day,
        cast(subtotal_cents as double) as subtotal_cents,
        cast(tax_paid_cents as double) as tax_paid_cents,
        cast(order_total_cents as decimal(12, 2)) as order_total_cents,
        cast(subtotal as double) as subtotal,
        cast(tax_paid as double) as tax_paid,
        cast(order_total as decimal(12, 2)) as order_total
    from {{ ref('stg_orders') }}
),

jnr_orders_items_agg as (
    -- JNR_ORDERS_ITEMS_AGG (Joiner, Master Outer Join): ORDER_ID = ORDER_ID1
    select
        master.order_id as order_id,
        master.customer_id as customer_id,
        master.location_id as location_id,
        master.ordered_at_day as ordered_at_day,
        master.subtotal as subtotal,
        master.tax_paid as tax_paid,
        master.order_total as order_total,
        detail.item_lines as item_lines,
        detail.item_revenue as item_revenue,
        detail.order_cogs as order_cogs,
        detail.order_gross_profit as order_gross_profit,
        detail.food_item_lines as food_item_lines,
        detail.drink_item_lines as drink_item_lines
    from agg_items_by_order as detail
    left join sq_stg_orders1 as master
        on (master.order_id = detail.order_id)
),

exp_order_financials as (
    -- EXP_ORDER_FINANCIALS (Expression)
    select
        order_id as order_id,
        customer_id as customer_id,
        location_id as location_id,
        ordered_at_day as ordered_at_day,
        subtotal as order_subtotal,
        tax_paid as order_tax_paid,
        order_total as order_total,
        (case when (item_lines is null) then 0 else item_lines end) as item_lines,
        (case when (item_revenue is null) then 0 else item_revenue end) as item_revenue,
        (case when (order_cogs is null) then 0 else order_cogs end) as order_cogs,
        (case when (order_gross_profit is null) then 0 else order_gross_profit end) as order_gross_profit,
        case when ((case when (item_revenue is null) then 0 else item_revenue end) = 0) then 0 else ((case when (order_gross_profit is null) then 0 else order_gross_profit end) / (case when (item_revenue is null) then 0 else item_revenue end)) end as order_gross_margin_pct,
        case when (subtotal = 0) then 0 else (tax_paid / subtotal) end as effective_tax_rate,
        (case when (food_item_lines is null) then 0 else food_item_lines end) as food_item_lines,
        (case when (drink_item_lines is null) then 0 else drink_item_lines end) as drink_item_lines,
        case when ((case when (item_lines is null) then 0 else item_lines end) = 0) then 0 else ((case when (food_item_lines is null) then 0 else food_item_lines end) / (case when (item_lines is null) then 0 else item_lines end)) end as food_share_of_lines,
        case when ((case when (item_lines is null) then 0 else item_lines end) = 0) then 0 else ((case when (drink_item_lines is null) then 0 else drink_item_lines end) / (case when (item_lines is null) then 0 else item_lines end)) end as drink_share_of_lines
    from jnr_orders_items_agg
),

srt_for_customer_seq as (
    -- SRT_FOR_CUSTOMER_SEQ (Sorter on customer_id asc, ordered_at_day asc, order_id asc): row order only matters to order-dependent logic downstream, so no ORDER BY here
    select
        customer_id as customer_id,
        ordered_at_day as ordered_at_day,
        order_id as order_id,
        location_id as location_id,
        order_subtotal as order_subtotal,
        order_tax_paid as order_tax_paid,
        order_total as order_total,
        item_lines as item_lines,
        item_revenue as item_revenue,
